            'type': 'pooling',
            'pool_size': pool_size
        })

    def add_dense_layer(self, units, activation='softmax'):
        self.layers.append({
            'type': 'dense',
            'units': units,
            'activation': activation
        })

    def summary(self):
        print('UltimateCNN Model Summary:')
        for i, layer in enumerate(self.layers):
            print(f'Layer {i+1}: {layer["type"]} - Parameters: {layer}')

